mapper.select:
select hstv.SCORE_TARGET_VALUE_ID, hstv.SCORE_TARGET_ID, hstv.LEFT_BRACKET, (case when hstv.FROM_VALUE = 'EXECLLENT_VALUE' then t2.EXECLLENT_VALUE when hstv.FROM_VALUE = 'GOOD_VALUE' then t2.GOOD_VALUE when hstv.FROM_VALUE = 'AVERAGE_VALUE' then t2.AVERAGE_VALUE when hstv.FROM_VALUE = 'POOR_VALUE' then t2.POOR_VALUE end) AS FROM_VALUE,
(case when hstv.TO_VALUE = 'EXECLLENT_VALUE' then t2.EXECLLENT_VALUE when hstv.TO_VALUE = 'GOOD_VALUE' then t2.GOOD_VALUE when hstv.TO_VALUE = 'AVERAGE_VALUE' then t2.AVERAGE_VALUE when hstv.TO_VALUE = 'POOR_VALUE' then t2.POOR_VALUE end) AS TO_VALUE, hstv.RIGHT_BRACKET, hstv.DESCRIPTION
from hls_score_target hst, hls_score_target_values hstv,(select qds.EXECLLENT_VALUE, qds.GOOD_VALUE, qds.AVERAGE_VALUE, qds.POOR_VALUE, qds.SCORE_TARGET_ID, qds.SCORE_TEMPLATE_HD_ID from qujian_data_source qds) t2 where hst.SCORE_TARGET_ID = t2.SCORE_TARGET_ID and hst.SCORE_TARGET_ID = hstv.SCORE_TARGET_ID and hst.SCORE_TARGET_ID = #{scoreTargetId} and t2.SCORE_TEMPLATE_HD_ID =#{scoreTemplateHdId}
${sqlPart}
